contracts/core/AppAccessControlled.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "../interfaces/IAppAuthority.sol";

interface ISonicFeeMRegistry {
    function selfRegister(uint256 projectID) external;
}

/// @title AppAccessControlled
/// @notice This contract is used to control access to the App contract
abstract contract AppAccessControlled is Initializable {
    /// @notice Event emitted when the authority is updated
    /// @param authority The new authority
    event AuthorityUpdated(IAppAuthority indexed authority);

    /// @notice The authority contract
    IAppAuthority public authority;

    /// @notice Initializes the AppAccessControlled contract
    /// @dev This function is only callable once
    /// @param _authority The address of the authority contract
    function __AppAccessControlled_init(address _authority) internal {
        _setAuthority(IAppAuthority(_authority));
    }

    /// @notice Modifier to check if the caller is a governor
    /// @dev This modifier is only callable by the governor
    modifier onlyGovernor() {
        _onlyGovernor();
        _;
    }

    /// @notice Modifier to check if the caller is a guardian or governor
    /// @dev This modifier is only callable by the guardian or governor
    modifier onlyGuardianOrGovernor() {
        _onlyGuardianOrGovernor();
        _;
    }

    /// @notice Modifier to check if the caller is a reserve manager
    /// @dev This modifier is only callable by the reserve manager
    modifier onlyReserveManager() {
        _onlyReserveManager();
        _;
    }

    /// @notice Modifier to check if the caller is a reserve depositor
    /// @dev This modifier is only callable by the reserve depositor
    modifier onlyReserveDepositor() {
        _onlyReserveDepositor();
        _;
    }

    /// @notice Modifier to check if the caller is a guardian
    /// @dev This modifier is only callable by the guardian
    modifier onlyGuardian() {
        _onlyGuardian();
        _;
    }

    /// @notice Modifier to check if the caller is a policy
    /// @dev This modifier is only callable by the policy
    modifier onlyPolicy() {
        _onlyPolicy();
        _;
    }

    /// @notice Modifier to check if the caller is the treasury
    /// @dev This modifier is only callable by the treasury
    modifier onlyTreasury() {
        _onlyTreasury();
        _;
    }

    /// @notice Modifier to check if the caller is an executor
    /// @dev This modifier is only callable by the executor
    modifier onlyExecutor() {
        _onlyExecutor();
        _;
    }

    /// @notice Modifier to check if the caller is a bond manager
    /// @dev This modifier is only callable by the bond manager
    modifier onlyBondManager() {
        _onlyBondManager();
        _;
    }

    /// @notice Modifier to check if the caller is a bridge
    /// @dev This modifier is only callable by the bridge
    modifier onlyBridge() {
        _onlyBridge();
        _;
    }

    /// @notice Modifier to check if the caller is a bridge
    /// @dev This modifier is only callable by the bridge
    modifier onlyBridgeOrGovernor() {
        _onlyBridgeOrGovernor();
        _;
    }

    /// @notice Modifier to check if the contract is not paused
    /// @dev This modifier is only callable if the contract is not paused
    modifier whenNotPaused() {
        _ensureUnpaused();
        _;
    }

    /// @notice Sets the authority for the contract
    /// @dev This function is only callable by the governor
    /// @param _newAuthority The address of the new authority
    function setAuthority(IAppAuthority _newAuthority) external onlyGovernor {
        _setAuthority(_newAuthority);
    }

    /// @notice Sets the authority for the contract
    /// @dev This function is only callable by the governor
    /// @param _newAuthority The address of the new authority
    function _setAuthority(IAppAuthority _newAuthority) internal {
        authority = _newAuthority;
        emit AuthorityUpdated(_newAuthority);
    }

    /// @notice Sets the project ID for the fee registry
    /// @dev This function is only callable by the governor
    /// @param registry The address of the fee registry
    /// @param projectID The project ID to set
    function setFeeMProjectId(address registry, uint256 projectID) external onlyGovernor {
        ISonicFeeMRegistry(registry).selfRegister(projectID);
    }

    function _ensureUnpaused() internal view {
        require(!authority.underEmergencyPause(), "PAUSED");
    }

    function _onlyBridgeOrGovernor() internal view {
        require(authority.isGovernor(msg.sender) || authority.bridge() == msg.sender, "UNAUTHORIZED");
    }

    function _onlyGovernor() internal view {
        require(authority.isGovernor(msg.sender), "UNAUTHORIZED");
    }

    function _onlyGuardianOrGovernor() internal view {
        require(authority.isGuardian(msg.sender) || authority.isGovernor(msg.sender), "UNAUTHORIZED");
    }

    function _onlyGuardian() internal view {
        require(authority.isGuardian(msg.sender), "UNAUTHORIZED");
    }

    function _onlyPolicy() internal view {
        require(authority.isPolicy(msg.sender), "UNAUTHORIZED");
    }

    function _onlyReserveManager() internal view {
        require(authority.isReserveManager(msg.sender), "UNAUTHORIZED");
    }

    function _onlyReserveDepositor() internal view {
        require(authority.isReserveDepositor(msg.sender), "UNAUTHORIZED");
    }

    function _onlyExecutor() internal view {
        require(authority.isExecutor(msg.sender), "UNAUTHORIZED");
    }

    function _onlyBondManager() internal view {
        require(authority.isBondManager(msg.sender), "UNAUTHORIZED");
    }

    function _onlyTreasury() internal view {
        require(authority.isTreasury(msg.sender), "UNAUTHORIZED");
    }

    function _onlyBridge() internal view {
        require(authority.bridge() == msg.sender, "UNAUTHORIZED");
    }
}

contracts/core/AppOptions.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "../interfaces/IApp.sol";
import "../interfaces/IAppStaking.sol";
import "../interfaces/IPermissionedERC20.sol";
import "../interfaces/IPermissionedERC20Factory.sol";
import "../interfaces/IAppOptions.sol";
import "./AppAccessControlled.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title AppOptions
/// @notice Implementation of the options system that allows users to buy and redeem options
/// @dev This contract handles options positions as NFTs
contract AppOptions is IAppOptions, AppAccessControlled, ERC721Enumerable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using SafeERC20 for IApp;

    /// @inheritdoc IAppOptions
    IApp public rzr;

    /// @inheritdoc IAppOptions
    IPermissionedERC20 public rzrTrackingToken;

    /// @inheritdoc IAppOptions
    uint256 public lastPositionId;

    /// @inheritdoc IAppOptions
    uint256 public lastOfferingId;

    mapping(uint256 => Position) private _positions;
    mapping(uint256 => Offering) private _offerings;

    constructor(address _authority, address _rzr, address _factory) ERC721("RZR Options", "oRZR") ReentrancyGuard() {
        __AppAccessControlled_init(_authority);
        rzr = IApp(_rzr);
        IPermissionedERC20Factory factory = IPermissionedERC20Factory(_factory);
        rzrTrackingToken = factory.createPermissionedERC20("RZR Option", "oRZR", 18);
    }

    modifier onlyOwnerOrAuthorized(uint256 tokenId) {
        _onlyOwnerOrAuthorized(tokenId);
        _;
    }

    /// @inheritdoc IAppOptions
    function createOffering(
        IERC20 quoteToken,
        uint256 dateEnd,
        uint256 dateStart,
        uint256 maxQuoteToken,
        uint256 redemptionPrice
    ) external onlyGovernor returns (uint256 offeringId) {
        offeringId = ++lastOfferingId;

        _offerings[offeringId] = Offering({
            quoteToken: quoteToken,
            enabled: true,
            dateEnd: dateEnd,
            dateStart: dateStart,
            maxQuoteToken: maxQuoteToken,
            filled: 0,
            redemptionPrice: redemptionPrice
        });

        // Transfer RZR tokens to the offering
        uint256 expectedRzr = maxQuoteToken * redemptionPrice / 1e18;
        rzr.safeTransferFrom(msg.sender, address(this), expectedRzr);

        emit OfferingCreated(offeringId, quoteToken, dateEnd, dateStart, maxQuoteToken, redemptionPrice);
    }

    /// @inheritdoc IAppOptions
    function cancelOffering(uint256 offeringId) external onlyGuardianOrGovernor {
        _offerings[offeringId].enabled = false;
        emit OfferingCanceled(offeringId);
    }

    /// @inheritdoc IAppOptions
    function buy(uint256 offeringId, uint256 quoteAmount, address receiver) external nonReentrant {
        Offering storage offering = _offerings[offeringId];
        require(offering.enabled, "Offering not enabled");
        require(offering.dateStart <= block.timestamp, "Offering not started");
        require(offering.dateEnd >= block.timestamp, "Offering ended");
        require(offering.maxQuoteToken >= offering.filled + quoteAmount, "Offering sold out");

        offering.quoteToken.safeTransferFrom(msg.sender, address(this), quoteAmount);
        offering.filled += quoteAmount;

        uint256 rzrAmountAllocated = quoteAmount * offering.redemptionPrice / 1e18;

        _positions[++lastPositionId] = Position({
            offeringId: offeringId,
            quoteAmountFilled: quoteAmount,
            quoteAmountRedeemed: 0,
            quoteAmountExercised: 0,
            rzrAmountAllocated: rzrAmountAllocated,
            rzrAmountRedeemed: 0,
            rzrAmountExercised: 0
        });

        _mint(receiver, lastPositionId);

        emit OptionBought(
            offeringId, lastPositionId, receiver, quoteAmount, rzrAmountAllocated, offering.redemptionPrice
        );
    }

    /// @inheritdoc IAppOptions
    function redeem(uint256 positionId, uint256 percentageE18)
        external
        nonReentrant
        onlyOwnerOrAuthorized(positionId)
    {
        Position storage position = _positions[positionId];
        Offering memory offering = _offerings[position.offeringId];

        uint256 quoteAmountToRedeem = position.quoteAmountFilled * percentageE18 / 1e18;
        uint256 rzrAmountToBurn = position.rzrAmountAllocated * percentageE18 / 1e18;

        position.quoteAmountRedeemed += quoteAmountToRedeem;
        position.rzrAmountRedeemed += rzrAmountToBurn;

        _checkPositionInvariants(position, offering);

        // refund and burn the RZR
        offering.quoteToken.safeTransfer(msg.sender, quoteAmountToRedeem);
        rzr.burn(rzrAmountToBurn);

        emit OptionRedeemed(positionId, msg.sender, quoteAmountToRedeem, rzrAmountToBurn);
    }

    /// @inheritdoc IAppOptions
    function excercise(uint256 positionId, uint256 percentageE18)
        external
        nonReentrant
        onlyOwnerOrAuthorized(positionId)
    {
        Position storage position = _positions[positionId];
        Offering memory offering = _offerings[position.offeringId];

        uint256 quoteAmountToExercise = position.quoteAmountFilled * percentageE18 / 1e18;
        uint256 rzrAmountToExercise = position.rzrAmountAllocated * percentageE18 / 1e18;

        position.rzrAmountExercised += rzrAmountToExercise;
        position.quoteAmountExercised += quoteAmountToExercise;

        _checkPositionInvariants(position, offering);

        // claim the underlying and transfer the RZR
        offering.quoteToken.safeTransfer(_treasury(), quoteAmountToExercise);
        rzr.safeTransfer(msg.sender, rzrAmountToExercise);

        emit OptionExercised(positionId, msg.sender, quoteAmountToExercise, rzrAmountToExercise);
    }

    /// @inheritdoc IAppOptions
    function getPosition(uint256 positionId) external view returns (Position memory) {
        return _positions[positionId];
    }

    /// @inheritdoc IAppOptions
    function getOffering(uint256 offeringId) external view returns (Offering memory) {
        return _offerings[offeringId];
    }

    /// @dev Check that the position invariants are satisfied
    function _checkPositionInvariants(Position memory p, Offering memory o) internal pure {
        uint256 quoteActioned = p.quoteAmountRedeemed + p.quoteAmountExercised;
        uint256 rzrActioned = p.rzrAmountRedeemed + p.rzrAmountExercised;

        // the total amount of quote tokens actioned must be less than or equal
        // to the total amount of quote tokens filled
        require(quoteActioned <= p.quoteAmountFilled, "invariant violated: I1");

        // the total amount of RZR tokens actioned must be less than or equal
        // to the total amount of RZR tokens allocated
        require(rzrActioned <= p.rzrAmountAllocated, "invariant violated: I2");

        // the total amount of quote tokens actioned must be equal to the total amount of
        // RZR tokens actioned by the redemption price
        require(quoteActioned * o.redemptionPrice / 1e18 == rzrActioned, "invariant violated: I3");
    }

    function _treasury() internal view returns (address) {
        return address(authority.treasury());
    }

    function _onlyOwnerOrAuthorized(uint256 tokenId) internal view {
        require(
            ownerOf(tokenId) == msg.sender || isApprovedForAll(ownerOf(tokenId), msg.sender), "Not owner or approved"
        );
    }
}

