// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "./IAppTreasury.sol";

/// @title IAppAuthority
/// @notice Interface for managing different roles and authorities in the application
/// @dev This interface defines the core access control functionality for the application, including role management,
/// treasury management, and candidate tracking for various roles in the system
interface IAppAuthority {
    /// @notice Emitted when the treasury address is updated
    /// @param newTreasury The address of the new treasury
    /// @param oldTreasury The address of the old treasury
    event TreasuryUpdated(address indexed newTreasury, address indexed oldTreasury);

    /// @notice Emitted when the operations treasury address is updated
    /// @param newOperationsTreasury The address of the new operations treasury
    /// @param oldOperationsTreasury The address of the old operations treasury
    event OperationsTreasuryUpdated(address indexed newOperationsTreasury, address indexed oldOperationsTreasury);

    /// @notice Emitted when the bridge address is updated
    /// @param newBridge The address of the new bridge
    /// @param oldBridge The address of the old bridge
    event BridgeUpdated(address indexed newBridge, address indexed oldBridge);

    /// @notice Adds a new governor to the system
    /// @param _newGovernor The address of the new governor to add
    function addGovernor(address _newGovernor) external;

    /// @notice Adds a new guardian to the system
    /// @param _newGuardian The address of the new guardian to add
    function addGuardian(address _newGuardian) external;

    /// @notice Adds a new policy to the system
    /// @param _newPolicy The address of the new policy to add
    function addPolicy(address _newPolicy) external;

    /// @notice Adds a new reserve manager to the system
    /// @param _newReserveManager The address of the new reserve manager to add
    function addReserveManager(address _newReserveManager) external;

    /// @notice Adds a new executor to the system
    /// @param _newExecutor The address of the new executor to add
    function addExecutor(address _newExecutor) external;

    /// @notice Adds a new bond manager to the system
    /// @param _newBondManager The address of the new bond manager to add
    function addBondManager(address _newBondManager) external;

    /// @notice Adds a new reserve depositor to the system
    /// @param _newReserveDepositor The address of the new reserve depositor to add
    function addReserveDepositor(address _newReserveDepositor) external;

    /// @notice Removes an existing governor from the system
    /// @param _oldGovernor The address of the governor to remove
    function removeGovernor(address _oldGovernor) external;

    /// @notice Removes an existing guardian from the system
    /// @param _oldGuardian The address of the guardian to remove
    function removeGuardian(address _oldGuardian) external;

    /// @notice Removes an existing policy from the system
    /// @param _oldPolicy The address of the policy to remove
    function removePolicy(address _oldPolicy) external;

    /// @notice Removes an existing reserve manager from the system
    /// @param _oldReserveManager The address of the reserve manager to remove
    function removeReserveManager(address _oldReserveManager) external;

    /// @notice Removes an existing executor from the system
    /// @param _oldExecutor The address of the executor to remove
    function removeExecutor(address _oldExecutor) external;

    /// @notice Removes an existing bond manager from the system
    /// @param _oldBondManager The address of the bond manager to remove
    function removeBondManager(address _oldBondManager) external;

    /// @notice Sets the operations treasury address
    /// @param _newOperationsTreasury The address of the new operations treasury
    function setOperationsTreasury(address _newOperationsTreasury) external;

    /// @notice Sets the treasury address
    /// @param _newTreasury The address of the new treasury
    function setTreasury(address _newTreasury) external;

    /// @notice Sets the bridge address
    /// @param _newBridge The address of the new bridge
    function setBridge(address _newBridge) external;

    /// @notice Removes an existing reserve depositor from the system
    /// @param _oldReserveDepositor The address of the reserve depositor to remove
    function removeReserveDepositor(address _oldReserveDepositor) external;

    /// @notice Checks if an address is a governor
    /// @param account The address to check
    /// @return bool True if the address is a governor, false otherwise
    function isGovernor(address account) external view returns (bool);

    /// @notice Checks if an address is a bond manager
    /// @param account The address to check
    /// @return bool True if the address is a bond manager, false otherwise
    function isBondManager(address account) external view returns (bool);

    /// @notice Checks if an address is a guardian
    /// @param account The address to check
    /// @return bool True if the address is a guardian, false otherwise
    function isGuardian(address account) external view returns (bool);

    /// @notice Checks if an address is a policy
    /// @param account The address to check
    /// @return bool True if the address is a policy, false otherwise
    function isPolicy(address account) external view returns (bool);

    /// @notice Checks if an address is an executor
    /// @param account The address to check
    /// @return bool True if the address is an executor, false otherwise
    function isExecutor(address account) external view returns (bool);

    /// @notice Checks if an address is the treasury
    /// @param account The address to check
    /// @return bool True if the address is the treasury, false otherwise
    function isTreasury(address account) external view returns (bool);

    /// @notice Checks if an address is a reserve manager
    /// @param account The address to check
    /// @return bool True if the address is a reserve manager, false otherwise
    function isReserveManager(address account) external view returns (bool);

    /// @notice Checks if an address is a reserve depositor
    /// @param account The address to check
    /// @return bool True if the address is a reserve depositor, false otherwise
    function isReserveDepositor(address account) external view returns (bool);

    /// @notice Returns the address of the operations treasury
    /// @return address The address of the operations treasury
    function operationsTreasury() external view returns (address);

    /// @notice Returns the treasury contract instance
    /// @return IAppTreasury The treasury contract instance
    function treasury() external view returns (IAppTreasury);

    /// @notice Returns the bridge address
    /// @return address The address of the bridge
    function bridge() external view returns (address);

    /// @notice Returns if the contract is under emergency pause
    /// @return bool True if the contract is under emergency pause, false otherwise
    function underEmergencyPause() external view returns (bool);

    /// @notice Returns an array of all candidates for a given role
    /// @param role The role to get candidates for (e.g., GOVERNOR_ROLE, GUARDIAN_ROLE, etc.)
    /// @return candidates Array of addresses that are candidates for the given role
    function getAllCandidates(bytes32 role) external view returns (address[] memory candidates);

    /// @notice Returns an array of all reserve depositor candidates
    /// @return candidates Array of addresses that are reserve depositor candidates
    function getAllReserveDepositorCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all executor candidates
    /// @return candidates Array of addresses that are executor candidates
    function getAllExecutorCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all policy candidates
    /// @return candidates Array of addresses that are policy candidates
    function getAllPolicyCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all reserve manager candidates
    /// @return candidates Array of addresses that are reserve manager candidates
    function getAllReserveManagerCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all guardian candidates
    /// @return candidates Array of addresses that are guardian candidates
    function getAllGuardianCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all governor candidates
    /// @return candidates Array of addresses that are governor candidates
    function getAllGovernorCandidates() external view returns (address[] memory candidates);

    /// @notice Returns an array of all bond manager candidates
    /// @return candidates Array of addresses that are bond manager candidates
    function getAllBondManagerCandidates() external view returns (address[] memory candidates);

    /// @notice Pauses the contract
    function emergencyPause() external;

    /// @notice Unpauses the contract
    function emergencyUnpause() external;
}

contracts/interfaces/IAppOptions.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "./IApp.sol";
import "./IPermissionedERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";

/// @title IAppOptions
/// @notice Interface for the AppOptions contract that manages RZR token option offerings
/// @dev Extends ERC721Enumerable to represent each option position as an NFT
interface IAppOptions is IERC721Enumerable {
    /// @notice Represents an individual option position held by a user
    /// @dev Each position is represented as an ERC721 token
    struct Position {
        /// @notice The ID of the offering this position belongs to
        uint256 offeringId;
        /// @notice Total amount of quote tokens used to fill this position
        uint256 quoteAmountFilled;
        /// @notice Amount of quote tokens that have been redeemed
        uint256 quoteAmountRedeemed;
        /// @notice Amount of quote tokens that have been exercised
        uint256 quoteAmountExercised;
        /// @notice Amount of RZR tokens allocated to this position
        uint256 rzrAmountAllocated;
        /// @notice Amount of RZR tokens that have been redeemed
        uint256 rzrAmountRedeemed;
        /// @notice Amount of RZR tokens that have been exercised
        uint256 rzrAmountExercised;
    }

    /// @notice Represents an option offering campaign
    /// @dev Defines the terms and conditions for an option offering period
    struct Offering {
        /// @notice The ERC20 token accepted as payment for this offering
        IERC20 quoteToken;
        /// @notice Whether this offering is currently active and accepting purchases
        bool enabled;
        /// @notice Timestamp when the offering ends
        uint256 dateEnd;
        /// @notice Timestamp when the offering starts
        uint256 dateStart;
        /// @notice Maximum amount of quote tokens that can be collected in this offering
        uint256 maxQuoteToken;
        /// @notice Current amount of quote tokens that have been filled
        uint256 filled;
        /// @notice Price in quote tokens to redeem the option (without exercising)
        uint256 redemptionPrice;
    }

    /// @notice Emitted when a new option offering is created
    /// @param offeringId The unique identifier for the newly created offering
    /// @param quoteToken The ERC20 token accepted as payment for this offering
    /// @param dateEnd Timestamp when the offering ends
    /// @param dateStart Timestamp when the offering starts
    /// @param maxQuoteToken Maximum amount of quote tokens that can be collected
    /// @param redemptionPrice Price in quote tokens to redeem the option
    event OfferingCreated(
        uint256 indexed offeringId,
        IERC20 quoteToken,
        uint256 dateEnd,
        uint256 dateStart,
        uint256 maxQuoteToken,
        uint256 redemptionPrice
    );

    /// @notice Emitted when a user buys an option position
    /// @param offeringId The ID of the offering being purchased from
    /// @param positionId The unique identifier for the newly created position (ERC721 token ID)
    /// @param receiver The address receiving the option position NFT
    /// @param quoteAmountFilled Amount of quote tokens used to purchase the option
    /// @param rzrAmountAllocated Amount of RZR tokens allocated to this position
    /// @param redemptionPrice The redemption price for this option
    event OptionBought(
        uint256 indexed offeringId,
        uint256 indexed positionId,
        address indexed receiver,
        uint256 quoteAmountFilled,
        uint256 rzrAmountAllocated,
        uint256 redemptionPrice
    );

    /// @notice Emitted when a user redeems their option position
    /// @param positionId The ID of the position being redeemed
    /// @param redeemer The address redeeming the option
    /// @param quoteAmountRedeemed Amount of quote tokens returned to the redeemer
    /// @param rzrAmountRedeemed Amount of RZR tokens returned from the position
    event OptionRedeemed(
        uint256 indexed positionId, address indexed redeemer, uint256 quoteAmountRedeemed, uint256 rzrAmountRedeemed
    );

    /// @notice Emitted when a user exercises their option position
    /// @param positionId The ID of the position being exercised
    /// @param exerciser The address exercising the option
    /// @param quoteAmountExercised Amount of quote tokens used to exercise the option
    /// @param rzrAmountExercised Amount of RZR tokens received from exercising
    event OptionExercised(
        uint256 indexed positionId, address indexed exerciser, uint256 quoteAmountExercised, uint256 rzrAmountExercised
    );

    /// @notice Emitted when an offering is canceled
    /// @param offeringId The ID of the offering being canceled
    event OfferingCanceled(uint256 indexed offeringId);

    /// @notice Returns the RZR token contract
    /// @return The IApp interface for the RZR token
    function rzr() external view returns (IApp);

    /// @notice Returns the RZR tracking token contract used for option accounting
    /// @return The IPermissionedERC20 interface for the tracking token
    function rzrTrackingToken() external view returns (IPermissionedERC20);

    /// @notice Returns the ID of the last created position
    /// @return The most recent position ID
    function lastPositionId() external view returns (uint256);

    /// @notice Returns the ID of the last created offering
    /// @return The most recent offering ID
    function lastOfferingId() external view returns (uint256);

    /// @notice Creates a new option offering
    /// @param quoteToken The ERC20 token to accept as payment
    /// @param dateEnd Timestamp when the offering ends
    /// @param dateStart Timestamp when the offering starts
    /// @param maxQuoteToken Maximum amount of quote tokens that can be collected
    /// @param redemptionPrice Price in quote tokens to redeem the option
    /// @return offeringId The unique identifier for the newly created offering
    function createOffering(
        IERC20 quoteToken,
        uint256 dateEnd,
        uint256 dateStart,
        uint256 maxQuoteToken,
        uint256 redemptionPrice
    ) external returns (uint256 offeringId);

    /// @notice Cancels an existing offering
    /// @param offeringId The ID of the offering to cancel
    function cancelOffering(uint256 offeringId) external;

    /// @notice Purchases an option position from an active offering
    /// @param offeringId The ID of the offering to purchase from
    /// @param quoteAmount Amount of quote tokens to spend on the option
    /// @param receiver Address that will receive the option position NFT
    function buy(uint256 offeringId, uint256 quoteAmount, address receiver) external;

    /// @notice Redeems an option position to recover quote tokens without exercising
    /// @param positionId The ID of the position to redeem
    /// @param percentageE18 Percentage of the position to redeem (in 18 decimal fixed point, where 1e18 = 100%)
    function redeem(uint256 positionId, uint256 percentageE18) external;

    /// @notice Exercises an option position to receive RZR tokens
    /// @param positionId The ID of the position to exercise
    /// @param percentageE18 Percentage of the position to exercise (in 18 decimal fixed point, where 1e18 = 100%)
    function excercise(uint256 positionId, uint256 percentageE18) external;

    /// @notice Retrieves the details of a specific position
    /// @param positionId The ID of the position to query
    /// @return The Position struct containing all position details
    function getPosition(uint256 positionId) external view returns (Position memory);

    /// @notice Retrieves the details of a specific offering
    /// @param offeringId The ID of the offering to query
    /// @return The Offering struct containing all offering details
    function getOffering(uint256 offeringId) external view returns (Offering memory);
}

contracts/interfaces/IAppOracle.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

interface IAppOracle {
    event OracleUpdated(address indexed token, address indexed oracle, uint256 maxStaleness);
    event FloorPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event PriceFetched(
        address indexed token, uint256 amount, uint256 rzrAmount, uint256 usdAmount, uint256 lastUpdatedAt
    );

    // Errors
    error OracleNotFound(address token);
    error OracleAlreadyExists(address token);
    error OracleInactive(address token);
    error InvalidOracleAddress();
    error InvalidTokenAddress();

    /// @notice Initializes the AppOracle contract
    /// @dev This function is only callable once
    /// @param _authority The address of the authority contract
    /// @param _app The address of the app contract
    function initialize(address _authority, address _app) external;

    /**
     * @notice Update the oracle for a token
     * @param token The token address
     * @param oracle The oracle contract
     */
    function updateOracle(address token, address oracle, uint256 maxStaleness) external;

    /**
     * @notice Get the price for a token
     * @param token The token address
     * @return rzrAmount The token price in RZR
     * @return usdAmount The token price in USD
     * @return lastUpdatedAt The timestamp of the last update
     */
    function getPrice(address token)
        external
        view
        returns (uint256 rzrAmount, uint256 usdAmount, uint256 lastUpdatedAt);

    /**
     * @notice Get the price for a token in RZR for an amount
     * @param token The token address
     * @param amount The amount of the token
     * @return rzrAmount The token price in RZR for the amount
     * @return usdAmount The token price in USD for the amount
     * @return lastUpdatedAt The timestamp of the last update
     */
    function getPriceForAmount(address token, uint256 amount)
        external
        view
        returns (uint256 rzrAmount, uint256 usdAmount, uint256 lastUpdatedAt);

    /**
     * @notice Get the price for a token in RZR for an amount in the floor price
     * @param token The token address
     * @param amount The amount of the token
     * @return rzrAmount The token price in RZR for the amount
     * @return usdAmount The token price in USD for the amount
     * @return lastUpdatedAt The timestamp of the last update
     */
    function getPriceForAmountInFloor(address token, uint256 amount)
        external
        view
        returns (uint256 rzrAmount, uint256 usdAmount, uint256 lastUpdatedAt);

    /**
     * @notice Get the floor price for RZR
     * @return price The RZR floor price
     */
    function getTokenPrice() external view returns (uint256);

    /**
     * @notice Set the floor price for RZR
     * @param newFloorPrice The new RZR price
     */
    function setTokenPrice(uint256 newFloorPrice) external;
}

contracts/interfaces/IAppStaking.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./ITotalSupplyOracle.sol";

/// @title IAppStaking
/// @notice Interface for the staking system that allows users to stake RZR tokens and earn rewards
/// @dev This interface extends IERC721Enumerable to provide NFT functionality for staking positions
interface IAppStaking is IERC721Enumerable {
    // Structs
    /// @notice Represents a staking position
    /// @param amount Amount of RZR tokens staked in the position
    /// @param declaredValue Self-declared value in RZR for harberger tax
    /// @param rewardPerTokenPaid Last reward per token paid to this position
    /// @param rewards Accumulated rewards for this position
    /// @param withdrawCooldownEnd Timestamp when withdraw cooldown period ends; if 0, position is not in withdraw cooldown
    /// @param withdrawCooldownStart Timestamp when withdraw cooldown period starts; if 0, position is not in withdraw cooldown
    /// @param buyCooldownEnd Timestamp when buy cooldown period ends; if 0, position is not in buy cooldown
    /// @param taxPerSecond Tax rate for this position
    /// @param taxCredit Tax credit for this position
    /// @param lastTaxCollectionTime Timestamp of last tax collection for this position
    struct Position {
        uint256 amount;
        uint256 declaredValue;
        uint256 rewardPerTokenPaid;
        uint256 rewards;
        uint256 withdrawCooldownEnd;
        uint256 withdrawCooldownStart;
        uint256 buyCooldownEnd;
        uint256 taxPerSecond;
        uint256 taxCredit;
        uint256 lastTaxCollectionTime;
    }

    struct Variables {
        uint256 harbergerTaxRate;
        uint256 resellFeeRate;
        uint256 withdrawCooldownPeriod;
        uint256 buyCooldownPeriod;
        uint256 lowDemandThreshold;
        uint256 highDemandThreshold;
        uint256 maxDepositFee;
    }

    /// @notice Emitted when variables are updated
    /// @param variables The new variables
    event VariablesUpdated(Variables variables);

    // Events
    /// @notice Emitted when a new staking position is created
    /// @param tokenId The ID of the created position NFT
    /// @param owner The address of the position owner
    /// @param amount The amount of RZR tokens staked
    /// @param declaredValue The self-declared value for harberger tax
    event PositionCreated(uint256 indexed tokenId, address indexed owner, uint256 amount, uint256 declaredValue);

    /// @notice Emitted when a position is migrated
    /// @param tokenId The ID of the migrated position NFT
    /// @param owner The address of the position owner
    /// @param amount The amount of RZR tokens staked
    /// @param declaredValue The self-declared value for harberger tax
    event PositionMigrated(uint256 indexed tokenId, address indexed owner, uint256 amount, uint256 declaredValue);

    /// @notice Emitted when variables are overwritten
    /// @param periodFinish The timestamp when the reward period finishes
    /// @param rewardRate The reward rate
    /// @param lastUpdateTime The timestamp of the last reward update
    /// @param rewardPerTokenStored The reward per token stored
    /// @param totalStaked The total amount of tokens staked
    event VariablesOverwritten(
        uint256 periodFinish,
        uint256 rewardRate,
        uint256 lastUpdateTime,
        uint256 rewardPerTokenStored,
        uint256 totalStaked
    );

    /// @notice Emitted when a staking position is sold
    /// @param tokenId The ID of the position NFT
    /// @param seller The address of the seller
    /// @param buyer The address of the buyer
    /// @param price The price paid for the position
    event PositionSold(uint256 indexed tokenId, address indexed seller, address indexed buyer, uint256 price);

    /// @notice Emitted when rewards are claimed from a position
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    /// @param amount The amount of rewards claimed
    event RewardsClaimed(uint256 indexed tokenId, address indexed owner, uint256 amount);

    /// @notice Emitted when tokens are unstaked from a position
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    /// @param amount The amount of tokens unstaked
    event PositionUnstaked(uint256 indexed tokenId, address indexed owner, uint256 amount);

    /// @notice Emitted when a position enters cooldown period
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    event CooldownStarted(uint256 indexed tokenId, address indexed owner);

    /// @notice Emitted when a position's cooldown period ends
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    event CooldownEnded(uint256 indexed tokenId, address indexed owner);

    /// @notice Emitted when a position is updated
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    /// @param newAmount The new amount of tokens staked
    /// @param newDeclaredValue The new declared value
    event PositionUpdated(uint256 indexed tokenId, address indexed owner, uint256 newAmount, uint256 newDeclaredValue);

    /// @notice Emitted when unstaking is cancelled
    /// @param tokenId The ID of the position NFT
    /// @param owner The address of the position owner
    event UnstakingCancelled(uint256 indexed tokenId, address indexed owner);

    /// @notice Emitted when new rewards are added to the staking pool
    /// @param reward The amount of rewards added
    event RewardAdded(uint256 reward);

    /// @notice Emitted when rewards are paid to a user
    /// @param user The address of the user receiving rewards
    /// @param reward The amount of rewards paid
    event RewardPaid(address indexed user, uint256 reward);

    /// @notice Emitted when upfront tax credit is set for a position
    /// @param tokenId The position ID
    /// @param creditAmount The amount of upfront tax credit set
    event UpfrontTaxCreditSet(uint256 indexed tokenId, uint256 creditAmount);

    /// @notice Emitted when upfront tax credit is consumed
    /// @param tokenId The position ID
    /// @param creditConsumed The amount of credit consumed
    /// @param remainingCredit The remaining credit amount
    event UpfrontTaxCreditConsumed(uint256 indexed tokenId, uint256 creditConsumed, uint256 remainingCredit);

    /// @notice Emitted when a position is split
    /// @param originalTokenId The ID of the original position NFT
    /// @param newTokenId The ID of the new position NFT
    /// @param owner The address of the position owner
    /// @param to The address to which the new position is split
    /// @param splitAmount The amount of tokens split
    /// @param splitDeclaredValue The declared value of the split position
    event PositionSplit(
        uint256 indexed originalTokenId,
        uint256 indexed newTokenId,
        address indexed owner,
        address to,
        uint256 splitAmount,
        uint256 splitDeclaredValue
    );

    /// @notice Emitted when a position is merged
    /// @param survivingTokenId The ID of the surviving position NFT
    /// @param mergedTokenId The ID of the merged position NFT
    /// @param owner The address of the position owner
    /// @param newAmount The new amount of tokens staked in the merged position
    /// @param newDeclaredValue The new declared value for harberger tax in the merged position
    event PositionMerged(
        uint256 indexed survivingTokenId,
        uint256 indexed mergedTokenId,
        address indexed owner,
        uint256 newAmount,
        uint256 newDeclaredValue
    );

    /// @notice Emitted when streaming tax is collected from a position
    /// @param tokenId The ID of the position NFT
    /// @param taxAmount The amount of tax collected
    event StreamingTaxCollected(uint256 indexed tokenId, uint256 taxAmount);

    /// @notice Emitted when streaming tax rate is updated for a position
    /// @param tokenId The ID of the position NFT
    /// @param oldRate The old streaming tax rate
    /// @param newRate The new streaming tax rate
    event StreamingTaxRateUpdated(uint256 indexed tokenId, uint256 oldRate, uint256 newRate);

    /// @notice Initializes the staking contract
    /// @param _appToken The address of the dre token
    /// @param _trackingToken The address of the tracking token
    /// @param _authority The address of the authority contract
    /// @param _burner The address of the burner contract
    function initialize(address _appToken, address _trackingToken, address _authority, address _burner) external;

    /// @notice Sets the variables
    /// @param _variables The new variables
    function setVariables(Variables memory _variables) external;

    /// @notice Gets the variables
    /// @return The variables
    function variables() external view returns (Variables memory);

    // View functions
    /// @notice Gets the last time rewards were applicable
    /// @return The timestamp of the last reward application
    function lastTimeRewardApplicable() external view returns (uint256);

    /// @notice Gets the current reward per token rate
    /// @return The reward per token rate
    function rewardPerToken() external view returns (uint256);

    /// @notice Gets the earned rewards for a specific position
    /// @param tokenId The ID of the position NFT
    /// @return The amount of rewards earned
    function earned(uint256 tokenId) external view returns (uint256);

    /// @notice Gets the total amount of tokens staked
    /// @return The total amount of staked tokens
    function totalStaked() external view returns (uint256);

    // State changing functions
    /// @notice Notifies the contract of new rewards to be distributed
    /// @param reward The amount of rewards to be distributed
    function notifyRewardAmount(uint256 reward) external;

    /// @notice Creates a new staking position
    /// @param _user The address of the user creating the position
    /// @param _amount The amount of tokens to stake
    /// @param _declaredValue The self-declared value for harberger tax
    /// @param _lockEnd The timestamp when the lock period ends
    /// @return tokenId The ID of the created position NFT
    /// @return taxPaid The amount of tax paid for the position
    function createPosition(address _user, uint256 _amount, uint256 _declaredValue, uint256 _lockEnd)
        external
        returns (uint256 tokenId, uint256 taxPaid);

    /// @notice Starts the unstaking process for a position
    /// @param tokenId The ID of the position NFT
    function startUnstaking(uint256 tokenId) external;

    /// @notice Completes the unstaking process for a position
    /// @param tokenId The ID of the position NFT
    function completeUnstaking(uint256 tokenId) external;

    /// @notice Buys a staking position
    /// @param tokenId The ID of the position NFT to buy
    function buyPosition(uint256 tokenId) external;

    /// @notice Claims rewards from a staking position
    /// @param tokenId The ID of the position NFT
    /// @return reward The amount of rewards claimed
    function claimRewards(uint256 tokenId) external returns (uint256 reward);

    /// @notice Increases the amount of tokens staked in a position
    /// @param tokenId The ID of the position NFT
    /// @param additionalAmount The additional amount of tokens to stake
    /// @param addtionalDeclaredValue The additional declared value
    /// @return taxPaid The amount of tax paid for the additional amount
    function increaseAmount(uint256 tokenId, uint256 additionalAmount, uint256 addtionalDeclaredValue)
        external
        returns (uint256 taxPaid);

    /// @notice Cancels the unstaking process for a position
    /// @param tokenId The ID of the position NFT
    function cancelUnstaking(uint256 tokenId) external;

    /// @notice Gets the details of a staking position
    /// @param tokenId The ID of the position NFT
    /// @return The position details
    function positions(uint256 tokenId) external view returns (Position memory);

    /// @notice Sets upfront tax credit for a position (governor only)
    /// @param tokenId The position ID
    /// @param creditAmount The amount of upfront tax credit to set
    function setUpfrontTaxCredit(uint256 tokenId, uint256 creditAmount) external;

    /// @notice Gets the remaining upfront tax credit for a position
    /// @param tokenId The position ID
    /// @return The remaining upfront tax credit
    function getUpfrontTaxCredit(uint256 tokenId) external view returns (uint256);

    /// @notice Gets the current reward rate
    /// @return The current reward rate
    function rewardRate() external view returns (uint256);

    /// @notice Gets the current reward per token rate
    /// @return The current reward per token rate
    function rewardPerTokenStored() external view returns (uint256);

    /// @notice Gets the last time rewards were applicable
    /// @return The timestamp of the last reward application
    function lastUpdateTime() external view returns (uint256);

    /// @notice Gets the current reward rate
    /// @return The current reward rate
    function periodFinish() external view returns (uint256);

    /// @notice Gets the address of the burner contract
    /// @return The address of the burner contract
    function burner() external view returns (address);

    /// @notice Gets the epoch duration
    /// @return The epoch duration
    function EPOCH_DURATION() external view returns (uint256);

    /// @notice Gets the app token
    /// @return The app token
    function appToken() external view returns (IERC20);

    /// @notice Splits a position into two positions, sending the new position to a specified address
    /// @param tokenId The ID of the position to split
    /// @param splitRatio The ratio to split the position
    /// @param to The address to receive the new position
    /// @return newTokenId The ID of the newly created position
    function splitPosition(uint256 tokenId, uint256 splitRatio, address to) external returns (uint256 newTokenId);

    /// @notice Merges two positions owned by the caller into a single position.
    /// @param tokenId1 The ID of the first position NFT (this one will survive).
    /// @param tokenId2 The ID of the second position NFT (this one will be burned).
    /// @return mergedTokenId The ID of the resulting merged position (equals tokenId1)
    function mergePositions(uint256 tokenId1, uint256 tokenId2) external returns (uint256 mergedTokenId);

    /// @notice Collects streaming tax from a position
    /// @param id The ID of the position NFT
    /// @return tax The amount of tax collected
    /// @return credit The amount of credit used
    function collectStreamingTax(uint256 id) external returns (uint256 tax, uint256 credit);

    /// @notice Calculates the streaming tax owed for a position
    /// @param id The ID of the position NFT
    /// @return tax The amount of tax owed
    function calculateStreamingTax(uint256 id) external view returns (uint256 tax);
}

contracts/interfaces/IAppTreasury.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity 0.8.28;

import "./IAppOracle.sol";
import "./IApp.sol";
import "./IRateProvider.sol";

interface IAppTreasury {
    /**
     * @notice Gets the app
     * @return app_ The app
     */
    function app() external view returns (IApp app_);

    /**
     * @notice allow approved address to deposit an asset for app
     * @param _amount uint256 amount of token to deposit
     * @param _token address of token to deposit
     * @param _profit uint256 amount of profit to mint
     * @return send_ uint256 amount of app minted
     */
    function deposit(uint256 _amount, address _token, uint256 _profit) external returns (uint256 send_);

    /**
     * @notice Returns the value of a token in RZR, 18 decimals
     * @param _token The address of the token
     * @param _amount The amount of the token
     * @return rzrValue_ The value of the token in RZR
     * @return usdValue_ The value of the token in USD
     */
    function tokenValueE18(address _token, uint256 _amount)
        external
        view
        returns (uint256 rzrValue_, uint256 usdValue_);

    /**
     * @notice Returns the value of a token in RZR, 18 decimals
     * @param _token The address of the token
     * @return rzrValue_ The value of the token in RZR
     * @return usdValue_ The value of the token in USD
     */
    function tokenValueE18(address _token) external view returns (uint256 rzrValue_, uint256 usdValue_);

    /**
     * @notice allow approved address to manage the reserves of the treasury
     * @param _token address of the token to manage
     * @param _amount amount of the token to manage
     * @param _recipient address of the recipient
     * @return rzrValue_ amount of app that was managed in RZR terms
     * @return usdValue_ amount of app that was managed in USD terms
     */
    function manage(address _token, uint256 _amount, address _recipient)
        external
        returns (uint256 rzrValue_, uint256 usdValue_);

    /**
     * @notice allow approved address to enable a token as a reserve
     * @param _address address to enable
     */
    function enable(address _address) external;

    /**
     * @notice allow approved address to disable a token as a reserve
     * @param _address address to disable
     */
    function disable(address _address) external;

    /**
     * @notice Returns the total reserves of the treasury in USD terms (including credit and debit)
     * @return totalReserves_ The total reserves of the treasury in USD terms
     * @dev This is the total USD reserves of the treasury, including credit and debit
     */
    function totalReservesUsd() external view returns (uint256);

    /**
     * @notice Returns the total reserves of the treasury in RZR terms (including credit and debit)
     * @return totalReserves_ The total reserves of the treasury in RZR terms
     * @dev This is the total RZR reserves of the treasury, including credit and debit
     */
    function totalReservesRzr() external view returns (uint256);

    /**
     * @notice Sets the reserve fee
     * @param _reserveFee The new reserve fee
     */
    function setReserveFee(uint256 _reserveFee) external;

    /**
     * @notice Syncs the reserves of the treasury
     */
    function syncReserves() external returns (uint256 usdReserves, uint256 rzrReserves);

    /**
     * @notice Calculates the total reserves of the treasury in RZR terms (including credit and debit)
     * @return usdReserves_ The total reserves of the treasury in USD terms
     * @return rzrReserves_ The total reserves of the treasury in RZR terms
     */
    function calculateReserves() external view returns (uint256 usdReserves_, uint256 rzrReserves_);

    /**
     * @notice Gets the reserve fee
     * @return reserveFee_ The reserve fee
     */
    function reserveFee() external view returns (uint256 reserveFee_);

    /**
     * @notice Gets the app oracle
     * @return appOracle_ The app oracle
     */
    function appOracle() external view returns (IAppOracle appOracle_);

    /**
     * @notice Gets the enabled tokens
     * @return enabledTokens_ The enabled tokens
     */
    function enabledTokens(address _token) external view returns (bool enabledTokens_);

    /**
     * @notice Gets the tokens enabled in the treasury
     * @return tokens_ The tokens
     */
    function tokens() external view returns (address[] memory tokens_);

    /**
     * @notice Gets the token at a given index in the enabled tokens array
     * @param _index The index of the token
     * @return token_ The token at the given index
     */
    function tokenAt(uint256 _index) external view returns (address token_);

    /**
     * @notice Gets the number of enabled tokens
     * @return length_ The number of enabled tokens
     */
    function enabledTokensLength() external view returns (uint256 length_);

    /**
     * @notice Registers a rate provider for an asset
     * @param _asset The asset to register the rate provider for
     * @param _rateProvider The rate provider to register
     */
    function registerRateProvider(address _asset, address _rateProvider) external;

    /**
     * @notice Sets the revenue destination
     * @param _revenueDestination The revenue destination
     */
    function setRevenueDestination(address _revenueDestination) external;

    /**
     * @notice Collects the revenue for an asset
     * @param _asset The asset to collect the revenue for
     */
    function collectRevenue(address _asset) external;

    /**
     * @notice Collects the revenue for multiple assets
     * @param _assets The assets to collect the revenue for
     */
    function collectRevenueMultiple(address[] calldata _assets) external;

    /**
     * @notice Gets the revenue destination
     * @return revenueDestination_ The revenue destination
     */
    function revenueDestination() external view returns (address revenueDestination_);

    /**
     * @notice Gets the rate provider for an asset
     * @param _asset The asset to get the rate provider for
     * @return rateProvider_ The rate provider
     */
    function rateProviders(address _asset) external view returns (address rateProvider_);

    /**
     * @notice Gets the rate snapshot for an asset
     * @param _asset The asset to get the rate snapshot for
     * @return rateSnapshot_ The rate snapshot
     */
    function rateSnapshots(address _asset) external view returns (uint256 rateSnapshot_);

    /* ========== EVENTS ========== */

    event Deposit(address indexed token, uint256 amount, uint256 usdValue, uint256 rzrValue);
    event Withdrawal(address indexed token, uint256 amount, uint256 usdValue, uint256 rzrValue);
    event Managed(address indexed token, uint256 amount);
    event ReservesAudited(uint256 indexed totalReserves, uint256 indexed totalReservesWithCredit);
    event Minted(address indexed caller, address indexed recipient, uint256 amount);
    event TokenEnabled(address addr, bool result);
    event ReserveFeeSet(uint256 newFee, uint256 oldFee);
    event RateProviderRegistered(address indexed asset, address indexed rateProvider, uint256 indexed rateSnapshot);
    event RevenueDestinationSet(address indexed revenueDestination);
    event RevenueCollected(
        address indexed asset, uint256 revenue, uint256 revenueToProtocol, uint256 revenueToTreasury
    );
}

